mapper.select:
WITH tab AS (
), TIME_TAB AS (
), SUM_TAB AS (
) SELECT TO_CHAR(SCHEDULE_DATE, 'YYYY"年"MM"月"DD"日"') SCHEDULE_DATE, PROCEDURE_CODE, TO_NUMBER(PROCEDURE_CODE) SORT_ORDER, ORDER_NO, SPEC_CODE, PLAN_PRODUCTION_QTY, ACTUAL_FINISH_QTY, FINISH_RATE * 100 || '%' FINISH_RATE, '1' DATA_TYPE /* 明细数据 */ FROM tab WHERE (PLAN_PRODUCTION_QTY != 0 OR ACTUAL_FINISH_QTY != 0) AND #{startTime,jdbcType=DATE} = #{endTime,jdbcType=DATE} /*只有一天的记录需要展示明细，多天的不用展示*/ UNION ALL SELECT TO_CHAR(SCHEDULE_DATE, 'YYYY"年"MM"月"DD"日"') SCHEDULE_DATE, PROCEDURE_CODE, TO_NUMBER(PROCEDURE_CODE) SORT_ORDER, TO_CHAR(COUNT(DISTINCT ORDER_NO)) ORDER_NO, TO_CHAR(COUNT(DISTINCT SPEC_CODE)) SPEC_CODE, SUM(PLAN_PRODUCTION_QTY) PLAN_PRODUCTION_QTY, SUM(ACTUAL_FINISH_QTY) ACTUAL_FINISH_QTY, SUM(FINISH_RATE) || '/' || COUNT(DISTINCT ORDER_NO) || '=' || CASE WHEN COUNT(DISTINCT SPEC_CODE) != 0 THEN TO_CHAR(ROUND(SUM(FINISH_RATE)/COUNT(DISTINCT ORDER_NO), 4) * 100, 'fm9999999990.00') ELSE '0.00' END || '%' FINISH_RATE, CASE WHEN #{startTime,jdbcType=DATE} = #{endTime,jdbcType=DATE} THEN '2' ELSE '1' END DATA_TYPE /* 如果查询日期相同返回汇总类型，否则返回明细类型 */ FROM ( SELECT SCHEDULE_DATE, PROCEDURE_CODE, ORDER_NO, SPEC_CODE, PLAN_PRODUCTION_QTY, ACTUAL_FINISH_QTY, CASE WHEN p1.param_value IS NOT NULL AND p2.param_value IS NOT NULL AND FINISH_RATE BETWEEN to_number(p1.param_value) / 100 AND to_number(p2.param_value) / 100 THEN 1 ELSE 0 END FINISH_RATE FROM tab LEFT JOIN T_CX_PARAMS p1 ON p1.param_code = 'REPORT_FINISH_RATE_LOWER_LIMIT' AND p1.del_flag = '0' LEFT JOIN T_CX_PARAMS p2 ON p2.param_code = 'REPORT_FINISH_RATE_UPPER_LIMIT' AND p2.del_flag = '0' WHERE PLAN_PRODUCTION_QTY != 0 OR ACTUAL_FINISH_QTY != 0 UNION ALL SELECT * FROM SUM_TAB ) GROUP BY SCHEDULE_DATE, PROCEDURE_CODE ORDER BY SCHEDULE_DATE, SORT_ORDER, DATA_TYPE

WITH tab AS (
), TIME_TAB AS (
), SUM_TAB AS (
) SELECT CASE WHEN MIN(SCHEDULE_DATE) != MAX(SCHEDULE_DATE) THEN TO_CHAR(MIN(SCHEDULE_DATE), 'YYYY"年"MM"月"DD"日"') || '-' || TO_CHAR(MAX(SCHEDULE_DATE), 'YYYY"年"MM"月"DD"日"') ELSE TO_CHAR(MAX(SCHEDULE_DATE), 'YYYY"年"MM"月"DD"日"') END SCHEDULE_DATE, PROCEDURE_CODE, TO_NUMBER(PROCEDURE_CODE) SORT_ORDER, TO_CHAR(COUNT(DISTINCT ORDER_NO)) ORDER_NO, TO_CHAR(COUNT(DISTINCT SPEC_CODE)) SPEC_CODE, SUM(PLAN_PRODUCTION_QTY) PLAN_PRODUCTION_QTY, SUM(ACTUAL_FINISH_QTY) ACTUAL_FINISH_QTY, SUM(FINISH_RATE) || '/' || COUNT(DISTINCT ORDER_NO) || '=' || CASE WHEN COUNT(DISTINCT SPEC_CODE) != 0 THEN TO_CHAR(ROUND(SUM(FINISH_RATE)/COUNT(DISTINCT ORDER_NO), 4) * 100, 'fm9999999990.00') ELSE '0.00' END || '%' FINISH_RATE, '1' DATA_TYPE FROM ( SELECT SCHEDULE_DATE, PROCEDURE_CODE, ORDER_NO, SPEC_CODE, PLAN_PRODUCTION_QTY, ACTUAL_FINISH_QTY, CASE WHEN p1.param_value IS NOT NULL AND p2.param_value IS NOT NULL AND FINISH_RATE BETWEEN to_number(p1.param_value) / 100 AND to_number(p2.param_value) / 100 THEN 1 ELSE 0 END FINISH_RATE FROM tab LEFT JOIN T_CX_PARAMS p1 ON p1.param_code = 'REPORT_FINISH_RATE_LOWER_LIMIT' AND p1.del_flag = '0' LEFT JOIN T_CX_PARAMS p2 ON p2.param_code = 'REPORT_FINISH_RATE_UPPER_LIMIT' AND p2.del_flag = '0' WHERE PLAN_PRODUCTION_QTY != 0 OR ACTUAL_FINISH_QTY != 0 UNION ALL SELECT * FROM SUM_TAB ) GROUP BY PROCEDURE_CODE ORDER BY SCHEDULE_DATE, SORT_ORDER, DATA_TYPE

mapper.sql:
SELECT SCHEDULE_DATE, PROCEDURE_CODE, ORDER_NO, SPEC_CODE, PLAN_PRODUCTION_QTY, ACTUAL_FINISH_QTY, CASE WHEN PLAN_PRODUCTION_QTY != 0 THEN ROUND(ACTUAL_FINISH_QTY/PLAN_PRODUCTION_QTY, 4) ELSE 0 END FINISH_RATE FROM ( SELECT R.SCHEDULE_DATE, '0' PROCEDURE_CODE, R.ORDER_NO, R.SAP_CODE SPEC_CODE, NVL(R.CLASS1_PLAN_QTY, 0) + NVL(R.CLASS2_PLAN_QTY, 0) + NVL(R.CLASS3_PLAN_QTY, 0) PLAN_PRODUCTION_QTY, NVL(F.CLASS1_FINISH_QTY, 0) + NVL(F.CLASS2_FINISH_QTY, 0) + NVL(F.CLASS3_FINISH_QTY, 0) ACTUAL_FINISH_QTY FROM T_LH_SCHEDULE_RESULT R LEFT JOIN T_LH_CLASS_SHIFT_FINISH_QTY F ON R.ORDER_NO = F.ORDER_NO AND F.DEL_FLAG = '0' WHERE R.DEL_FLAG = '0' AND R.SCHEDULE_DATE BETWEEN #{startTime} AND #{endTime}
UNION
SELECT R.SCHEDULE_DATE, '1' PROCEDURE_CODE, R.ORDER_NO, R.EMBRYO_CODE SPEC_CODE, NVL(R.CLASS1_PLAN_QTY, 0) + NVL(R.CLASS2_PLAN_QTY, 0) + NVL(R.CLASS3_PLAN_QTY, 0) PLAN_PRODUCTION_QTY, NVL(F.CLASS1_FINISH_QTY, 0) + NVL(F.CLASS2_FINISH_QTY, 0) + NVL(F.CLASS3_FINISH_QTY, 0) ACTUAL_FINISH_QTY FROM T_CX_SCHEDULE_RESULT R LEFT JOIN T_CX_CLASS_SHIFT_FINISH_QTY F ON R.ORDER_NO = F.ORDER_NO AND F.DEL_FLAG = '0' WHERE R.DEL_FLAG = '0' AND R.SCHEDULE_DATE BETWEEN #{startTime} AND #{endTime}
UNION
SELECT R.SCHEDULE_DATE, '2' PROCEDURE_CODE, R.ORDER_NO, R.TREAD_CODE SPEC_CODE, NVL(R.DAY_PLAN_QTY, 0) + NVL(R.NIGHT_PLAN_QTY, 0) PLAN_PRODUCTION_QTY, NVL(F.DAY_FINISH_QTY, 0) + NVL(F.NIGHT_FINISH_QTY, 0) ACTUAL_FINISH_QTY FROM T_TM_SCHEDULE_RESULT R LEFT JOIN T_TM_DAY_FINISH_QTY F ON R.ORDER_NO = F.ORDER_NO AND F.DEL_FLAG = '0' WHERE R.DEL_FLAG = '0' AND R.SCHEDULE_DATE BETWEEN #{startTime} AND #{endTime}
UNION
SELECT R.SCHEDULE_DATE, '3' PROCEDURE_CODE, R.ORDER_NO, R.SIDEWALL_CODE SPEC_CODE, NVL(R.DAY_PLAN_QTY, 0) + NVL(R.NIGHT_PLAN_QTY, 0) PLAN_PRODUCTION_QTY, NVL(F.DAY_FINISH_QTY, 0) + NVL(F.NIGHT_FINISH_QTY, 0) ACTUAL_FINISH_QTY FROM T_TC_SCHEDULE_RESULT R LEFT JOIN T_TC_DAY_FINISH_QTY F ON R.ORDER_NO = F.ORDER_NO AND F.DEL_FLAG = '0' WHERE R.DEL_FLAG = '0' AND R.SCHEDULE_DATE BETWEEN #{startTime} AND #{endTime}
UNION
SELECT R.SCHEDULE_DATE, '4' PROCEDURE_CODE, R.ORDER_NO, R.LINING_CODE SPEC_CODE, NVL(R.DAY_PLAN_QTY, 0) + NVL(R.NIGHT_PLAN_QTY, 0) PLAN_PRODUCTION_QTY, NVL(F.DAY_FINISH_QTY, 0) + NVL(F.NIGHT_FINISH_QTY, 0) ACTUAL_FINISH_QTY FROM T_NC_SCHEDULE_RESULT R LEFT JOIN T_NC_DAY_FINISH_QTY F ON R.ORDER_NO = F.ORDER_NO AND F.DEL_FLAG = '0' WHERE R.DEL_FLAG = '0' AND R.SCHEDULE_DATE BETWEEN #{startTime} AND #{endTime}
UNION
SELECT R.SCHEDULE_DATE, '5' PROCEDURE_CODE, R.ORDER_NO, R.BEAD_CODE SPEC_CODE, NVL(R.MID_PLAN_QTY, 0) + NVL(R.NIGHT_PLAN_QTY, 0) + NVL(R.DAY_PLAN_QTY, 0) PLAN_PRODUCTION_QTY, NVL(F.MID_FINISH_QTY, 0) + NVL(F.NIGHT_FINISH_QTY, 0) + NVL(F.DAY_FINISH_QTY, 0) ACTUAL_FINISH_QTY FROM T_TQ_SCHEDULE_RESULT R LEFT JOIN T_TQ_DAY_FINISH_QTY F ON R.ORDER_NO = F.ORDER_NO AND F.DEL_FLAG = '0' WHERE R.DEL_FLAG = '0' AND R.SCHEDULE_DATE BETWEEN #{startTime} AND #{endTime}
UNION
SELECT R.SCHEDULE_DATE, '6' PROCEDURE_CODE, R.ORDER_NO, R.STEEL_RING_CODE SPEC_CODE, NVL(R.MID_PLAN_QTY, 0) + NVL(R.NIGHT_PLAN_QTY, 0) + NVL(R.DAY_PLAN_QTY, 0) PLAN_PRODUCTION_QTY, NVL(F.MID_FINISH_QTY, 0) + NVL(F.NIGHT_FINISH_QTY, 0) + NVL(F.DAY_FINISH_QTY, 0) ACTUAL_FINISH_QTY FROM T_GSQ_SCHEDULE_RESULT R LEFT JOIN T_GSQ_DAY_FINISH_QTY F ON R.ORDER_NO = F.ORDER_NO AND F.DEL_FLAG = '0' WHERE R.DEL_FLAG = '0' AND R.SCHEDULE_DATE BETWEEN #{startTime} AND #{endTime}
UNION
SELECT R.SCHEDULE_DATE, '7' PROCEDURE_CODE, R.ORDER_NO, R.STEEL_STRIP_CODE1 SPEC_CODE, NVL(R.NIGHT_PLAN_QTY1, 0) + NVL(R.DAY_PLAN_QTY1, 0) PLAN_PRODUCTION_QTY, NVL(F.NIGHT_FINISH_QTY, 0) + NVL(F.DAY_FINISH_QTY, 0) ACTUAL_FINISH_QTY FROM T_CD15_SCHEDULE_RESULT R LEFT JOIN T_CD15_DAY_FINISH_QTY F ON R.ORDER_NO = F.ORDER_NO AND F.DEL_FLAG = '0' WHERE R.DEL_FLAG = '0' AND R.SCHEDULE_DATE BETWEEN #{startTime} AND #{endTime}
UNION
SELECT R.SCHEDULE_DATE, '8' PROCEDURE_CODE, R.ORDER_NO, R.CLOTH_CODE SPEC_CODE, NVL(R.NIGHT_PLAN_QTY, 0) + NVL(R.DAY_PLAN_QTY, 0) PLAN_PRODUCTION_QTY, NVL(F.NIGHT_FINISH_QTY, 0) + NVL(F.DAY_FINISH_QTY, 0) ACTUAL_FINISH_QTY FROM T_CD90_SCHEDULE_RESULT R LEFT JOIN T_CD90_DAY_FINISH_QTY F ON R.ORDER_NO = F.ORDER_NO AND F.DEL_FLAG = '0' WHERE R.DEL_FLAG = '0' AND R.SCHEDULE_DATE BETWEEN #{startTime} AND #{endTime}
UNION
SELECT R.SCHEDULE_DATE, '9' PROCEDURE_CODE, R.ORDER_NO, R.BIG_ROLL_CODE SPEC_CODE, NVL(R.CLASS1_PLAN, 0) + NVL(R.CLASS2_PLAN, 0) + NVL(R.CLASS3_PLAN, 0) PLAN_PRODUCTION_QTY, 0 ACTUAL_FINISH_QTY FROM T_GDYY_SCHEDULE_RESULT R WHERE R.DEL_FLAG = '0' AND R.SCHEDULE_DATE BETWEEN #{startTime} AND #{endTime}
UNION
SELECT R.SCHEDULE_DATE, '10' PROCEDURE_CODE, R.ORDER_NO, R.BIG_ROLL_CODE SPEC_CODE, NVL(R.NIGHT_PLAN_QTY, 0) + NVL(R.DAY_PLAN_QTY, 0) PLAN_PRODUCTION_QTY, NVL(F.NIGHT_FINISH_QTY, 0) + NVL(F.DAY_FINISH_QTY, 0) ACTUAL_FINISH_QTY FROM T_XWYY_SCHEDULE_RESULT R LEFT JOIN T_XWYY_DAY_FINISH_QTY F ON R.ORDER_NO = F.ORDER_NO AND F.DEL_FLAG = '0' WHERE R.DEL_FLAG = '0' AND R.SCHEDULE_DATE BETWEEN #{startTime} AND #{endTime} )
